// Windows: link the compiled icon resource (packaging/theames.res, generated by
// make-icon.py, kept outside the source tree) into the launcher so Explorer and the taskbar show its icon.
fn main() {
    println!("cargo:rerun-if-changed=packaging/theames.res");
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows") {
        let dir = std::env::var("CARGO_MANIFEST_DIR").unwrap();
        println!("cargo:rustc-link-arg-bin=theames={dir}/packaging/theames.res");
    }
}
